def can_concatenate_with_k_scissors(n, m, k, s, t):
    # Check if the length of s is sufficient
    if n < 2 * k:
        return "No"

    # Create a hash map to store the starting indices of all substrings of length k
    substring_map = {}
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if substring not in substring_map:
            substring_map[substring] = []
        substring_map[substring].append(i)

    # Try to find two non-intersecting substrings that can form t
    for i in range(n - k + 1):
        substring1 = s[i:i + k]
        if substring1 in substring_map:
            for j in substring_map[substring1]:
                if j != i and abs(j - i) >= k:
                    # Check if the concatenation of these two substrings contains t
                    concatenated = substring1 + s[j:j + k]
                    if t in concatenated:
                        return "Yes", i + 1, j + 1

    return "No"

